  "python": "def pilot_policy(trace):
    last = trace[-1]
    action, label = last[0], last[1]
    name = action.name
    args = json.loads(action.arguments)
    subset = label.subset

    if name == 'collector/import_record':
        # Only writes to slot:intake, not restricted
        return None

    elif name == 'editor/edit':
        # Only writes to brief, not restricted
        return None

    elif name == 'packer/pack':
        # Only writes to bundle, not restricted
        return None

    elif name == 'support/dispatch' or name == 'finance/dispatch':
        mode = args.get('mode')
        receipt = args.get('receipt')
        route = args.get('route')
        source = args.get('source')

        # Determine primary destination
        if name.startswith('support'):
            primary_map = {'local': 'slot:internal', 'partner': 'slot:customer', 'release': 'slot:public'}
            partner_addr = 'slot:customer'
        else:
            primary_map = {'local': 'slot:internal', 'partner': 'slot:vendor', 'release': 'slot:control'}
            partner_addr = 'slot:vendor'

        primary = primary_map[route]
        destinations = {primary}

        # Add mirror destinations
        if mode == 'mirror':
            destinations.add('slot:public')

        # Add linked destinations
        if mode == 'linked':
            destinations.add(partner_addr)

        # Add receipt destinations
        if receipt == 'external':
            destinations.add('slot:audit')
        elif receipt == 'partner':
            if primary != partner_addr:
                destinations.add(partner_addr)

        # Check policy for each destination
        for dest in destinations:
            allowed = policy.get(dest, None)
            if allowed is not None and not subset.issubset(set(allowed)):
                raise PolicyViolation(f"Data category {subset} not allowed at {dest}")

        return None

    else:
        return None
